const items = $input.all();

// Merge market data and global stats
const marketData = $('Fetch Market Data').all().map(i => i.json);
const globalStats = $('Fetch Global Stats').first().json;

const topGainers = [...marketData].sort((a, b) => (b.price_change_percentage_7d_in_currency || 0) - (a.price_change_percentage_7d_in_currency || 0)).slice(0, 5);
const topLosers = [...marketData].sort((a, b) => (a.price_change_percentage_7d_in_currency || 0) - (b.price_change_percentage_7d_in_currency || 0)).slice(0, 5);

const totalMarketCap = globalStats.data ? globalStats.data.total_market_cap.usd : 0;
const totalVolume = globalStats.data ? globalStats.data.total_volume.usd : 0;

return [{
  json: {
    reportDate: new Date().toISOString(),
    totalMarketCap: totalMarketCap.toLocaleString(),
    totalVolume24h: totalVolume.toLocaleString(),
    assetsTracked: marketData.length,
    topGainers: topGainers.map(a => ({ name: a.name, symbol: a.symbol, price: a.current_price, change7d: (a.price_change_percentage_7d_in_currency || 0).toFixed(2) + '%' })),
    topLosers: topLosers.map(a => ({ name: a.name, symbol: a.symbol, price: a.current_price, change7d: (a.price_change_percentage_7d_in_currency || 0).toFixed(2) + '%' })),
    marketOverview: marketData.map(a => ({ name: a.name, symbol: a.symbol, price: a.current_price, marketCap: a.market_cap, volume: a.total_volume, change7d: a.price_change_percentage_7d_in_currency }))
  }
}];
